query:
query games($ids: [ID!]!, $scope: PeriodScore) {
  games(ids: $ids) {
    ...GameFragment
    __typename
  }
}

fragment GameFragment on Game {
  id
  status
  updatedAt
  lastEventRecordedAt
  statistics {
    home {
      statisticsV2 {
        type {
          type
          value
          __typename
        }
        count
        __typename
      }
      players {
        id
        profileID
        name
        playerNumber
        periodStatistics {
          period {
            value
            __typename
          }
          side
          type
          statistics {
            type {
              value
              __typename
            }
            count
            __typename
          }
          status
          displayOrder
          __typename
        }
        statistics {
          type {
            value
            __typename
          }
          count
          __typename
        }
        permitType
        __typename
      }
      __typename
    }
    away {
      statisticsV2 {
        type {
          type
          value
          __typename
        }
        count
        __typename
      }
      players {
        id
        profileID
        name
        playerNumber
        periodStatistics {
          period {
            value
            __typename
          }
          side
          type
          statistics {
            type {
              value
              __typename
            }
            count
            __typename
          }
          status
          displayOrder
          __typename
        }
        statistics {
          type {
            type
            value
            __typename
          }
          count
          __typename
        }
        permitType
        __typename
      }
      __typename
    }
    shared {
      period {
        value
        __typename
      }
      side
      __typename
    }
    __typename
  }
  result {
    home {
      statistics {
        type {
          value
          __typename
        }
        count
        __typename
      }
      periods(scope: $scope) {
        period {
          label
          shortName
          value
          __typename
        }
        statistics {
          type {
            type
            value
            __typename
          }
          count
          __typename
        }
        type
        role
        closureStatus
        overtimeSequenceNo
        __typename
      }
      __typename
    }
    away {
      statistics {
        type {
          type
          value
          __typename
        }
        count
        __typename
      }
      periods(scope: $scope) {
        period {
          label
          shortName
          value
          __typename
        }
        statistics {
          type {
            type
            value
            __typename
          }
          count
          __typename
        }
        type
        role
        closureStatus
        overtimeSequenceNo
        __typename
      }
      __typename
    }
    currentPeriod {
      value
      primarySide
      __typename
    }
    __typename
  }
  break
  latestEvent {
    id
    title
    description
    visible
    requireReload
    sportEventStamp
    eventSection
    timestamp
    previousEventID
    side
    period
    ... on ScoreEvent {
      progressiveScore
      score
      __typename
    }
    ... on FoulEvent {
      type
      __typename
    }
    ... on DismissalEvent {
      icon
      __typename
    }
    ... on ExtraEvent {
      icon
      __typename
    }
    ... on PeriodSummaryEvent {
      summary {
        ... on OverSummary {
          side
          batters {
            playerID
            name
            score
            __typename
          }
          bowlers {
            playerID
            name
            score
            __typename
          }
          title
          progressiveStatistics
          scoreSummary
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  clock {
    overtimeSequenceNo
    period
    periodValue
    status
    time
    lastUpdatedAt
    __typename
  }
  __typename
}
